#!/usr/bin/env bash
#
# Execute the DGM derived-results trigger against a real PostgreSQL, with the
# spreadsheet row generated by the real TypeScript.
#
# WHY THIS EXISTS. `tg_record_derived_results` (migration 0025) is the only
# part of the DGM path that lives in PL/pgSQL, so vitest cannot reach it: the
# unit tests prove what `validateStagePayload` puts in the row, and stop at the
# boundary. What happens to that row afterwards -- which cells become stored
# results, how a blank cell is treated, whether `column_letter_to_index` lands
# on the right slot given Postgres arrays are 1-indexed and the TypeScript one
# is 0-indexed -- was asserted by nobody.
#
# It also covers the one case no other test can reach at all: a CORRECTION that
# blanks cells, where the trigger must DELETE a previously stored result rather
# than leave a stale value or write a zero.
#
# WHAT MAKES IT A SEAM TEST. The projected row is not typed into this file. It
# is emitted by scripts/dgm-projected-row.ts, which calls the same
# `validateStagePayload` the Edge Function calls, so a drift between what
# TypeScript computes and what SQL stores fails here. A hand-copied row would
# only ever test the transcription.
#
# WHAT A PASS DOES NOT MEAN. This is plain PostgreSQL with
# scripts/local-sql-shim.sql, not Supabase: RLS is not exercised under a real
# JWT and no HTTP request is made. See the caveats in verify-migrations.sh.
#
# Usage:
#   scripts/verify-dgm-trigger.sh [dbname]
#
set -euo pipefail

cd "$(dirname "$0")/.."

DB="${1:-bff_dgm_trigger_check}"
ROWS="$(mktemp -t dgm_rows).sql"
trap 'rm -f "$ROWS"' EXIT

if ! command -v psql >/dev/null 2>&1; then
  echo "psql not found. Install PostgreSQL, or run 'supabase db reset' with Docker." >&2
  exit 1
fi

echo "== Applying migrations to $DB =="
scripts/verify-migrations.sh "$DB" >/dev/null

echo "== Generating the projected row from the real validator =="
npx vite-node scripts/dgm-projected-row.ts "$ROWS"

echo "== Executing the trigger =="
# Every assertion is a DO block that RAISEs on mismatch, so ON_ERROR_STOP makes
# a failure exit non-zero. The whole run is wrapped in a transaction that rolls
# back, so the database is left exactly as the migrations made it.
psql -X -q -v rows_file="$ROWS" -f scripts/dgm-trigger-check.sql "$DB" 2>&1 \
  | sed -e 's/^psql:[^ ]*: NOTICE:  /  /' -e '/^$/d'

echo "== Done. The trigger stores, parses and deletes as 0025 says it does. =="
